INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2590558, 356171, 43774, '<td valign="top">Love it! I was hoping to get a picture of an old washed up boat too but I didn''t get a chance to go looking for one.</td>', 'Love it! I was hoping to get a picture of an old washed up boat too but I didn''t get a chance to go looking for one.', '2006-07-05 22:39:51.000000', NULL, 1),
(2590565, 356641, 43774, '<td valign="top">Wow that''s an interesting object. Very good photograph of it, love the reflection and you exposed the flame perfectly.</td>', 'Wow that''s an interesting object. Very good photograph of it, love the reflection and you exposed the flame perfectly.', '2006-07-05 22:41:26.000000', NULL, 1),
(2590567, 356363, 55199, '<td valign="top">my eyes are drawn to the red and green lights and can''t decide which to rest on.  I think this would be much stronger if the red light and rocks were cropped out, bringing our eyes only to the stationary green light and rocks.</td>', 'my eyes are drawn to the red and green lights and can''t decide which to rest on.  I think this would be much stronger if the red light and rocks were cropped out, bringing our eyes only to the stationary green light and rocks.', '2006-07-05 22:41:58.000000', NULL, 1),
(2590579, 358287, 55199, '<td valign="top">Nice idea and composition.  I''d like it more if the tree were a little greener, but its still very nice.</td>', 'Nice idea and composition.  I''d like it more if the tree were a little greener, but its still very nice.', '2006-07-05 22:45:05.000000', NULL, 1),
(2590584, 356314, 43774, '<td valign="top">What a beautiful photo. Yes, the person appears to be still but that is just a tiny part of your photo. The moving water takes up most of your photo and when I look at it I do not think "stationary", but rather movement.</td>', 'What a beautiful photo. Yes, the person appears to be still but that is just a tiny part of your photo. The moving water takes up most of your photo and when I look at it I do not think "stationary", but rather movement.', '2006-07-05 22:46:22.000000', NULL, 1),
(2590586, 358137, 43774, '<td valign="top">I love the lighting in this....beautiful sky too.</td>', 'I love the lighting in this....beautiful sky too.', '2006-07-05 22:46:37.000000', NULL, 1),
(2590588, 358475, 43774, '<td valign="top">How cool, that rock looks like an egg to me. Other than all the dirt spots in the sky I really like this.</td>', 'How cool, that rock looks like an egg to me. Other than all the dirt spots in the sky I really like this.', '2006-07-05 22:47:47.000000', NULL, 1),
(2590590, 356314, 61012, '<td valign="top">I understand the contrast between movement and stillness but I think the motion is overpowering</td>', 'I understand the contrast between movement and stillness but I think the motion is overpowering', '2006-07-05 22:48:23.000000', NULL, 1),
(2590602, 356161, 55199, '<td valign="top">Not sure this conveys a sense of something stationary.  Seems like it should have been entered into the glass challenge last week, it probably would have done fairly well there.</td>', 'Not sure this conveys a sense of something stationary.  Seems like it should have been entered into the glass challenge last week, it probably would have done fairly well there.', '2006-07-05 22:51:14.000000', NULL, 1),
