(2590862, 358108, 24454, '<td valign="top">This is so cute!!!  Extra points for the cute factor!!!   I LOVE it!!!  9</td>', 'This is so cute!!!  Extra points for the cute factor!!!   I LOVE it!!!  9', '2006-07-06 00:06:06.000000', NULL, 1),
(2590865, 357842, 61030, '<td valign="top">There''s a little too much backlighting, the flag should be more highlighted... unless that''s the effect you''re looking for! =)</td>', 'There''s a little too much backlighting, the flag should be more highlighted... unless that''s the effect you''re looking for! =)', '2006-07-06 00:06:14.000000', NULL, 1),
(2590867, 358674, 55199, '<td valign="top">Nice idea. I think I would have liked this better in color, and with a little bit (~1/2") of the top cropped off.</td>', 'Nice idea. I think I would have liked this better in color, and with a little bit (~1/2") of the top cropped off.', '2006-07-06 00:06:26.000000', NULL, 1),
(2590873, 358515, 61030, '<td valign="top">Great shot. The lines flow so well together.</td>', 'Great shot. The lines flow so well together.', '2006-07-06 00:07:02.000000', NULL, 1),
(2590874, 358606, 24454, '<td valign="top">Tee hee. . . cute concept.   I never thought of the poor ol'' fire hydrant as having no choice in the matter!   I like it.</td>', 'Tee hee. . . cute concept.   I never thought of the poor ol'' fire hydrant as having no choice in the matter!   I like it.', '2006-07-06 00:07:10.000000', NULL, 1),
(2590877, 358193, 61030, '<td valign="top">I like all of the texture.</td>', 'I like all of the texture.', '2006-07-06 00:07:32.000000', NULL, 1),
