INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2600431, 358579, 60047, '<td valign="top">Nice idea!</td>', 'Nice idea!', '2006-07-08 12:45:57.000000', NULL, 1),
(2600433, 356263, 60047, '<td valign="top">Needs better focus</td>', 'Needs better focus', '2006-07-08 12:47:17.000000', NULL, 1),
(2600435, 356502, 60047, '<td valign="top">I would like a better wing position.</td>', 'I would like a better wing position.', '2006-07-08 12:48:16.000000', NULL, 1),
(2600437, 356654, 60047, '<td valign="top">Though the subject is not completely in focus, the flower structure allows for this. Great shot.</td>', 'Though the subject is not completely in focus, the flower structure allows for this. Great shot.', '2006-07-08 12:49:30.000000', NULL, 1),
(2600441, 356171, 60047, '<td valign="top">Fascinating shot</td>', 'Fascinating shot', '2006-07-08 12:51:25.000000', NULL, 1),
(2600446, 358241, 60047, '<td valign="top">This tight shot works well with the theme.</td>', 'This tight shot works well with the theme.', '2006-07-08 12:55:01.000000', NULL, 1),
(2600451, 358601, 61679, '<td valign="top">This is the perfect title for this image.  I have two suggestions that I think could help this image.  First, crop off about 50% of the empty sky above the boat mast and the space shuttle.  This will help move the horizan closer to the majic 1/3 mark.  Second, I would like to see the sky darkened and the water lightened via using levels.  This should help bring out some of the wonderful detail in the waves and draw less attention to the sky.</td>', 'This is the perfect title for this image.  I have two suggestions that I think could help this image.  First, crop off about 50% of the empty sky above the boat mast and the space shuttle.  This will help move the horizan closer to the majic 1/3 mark.  Second, I would like to see the sky darkened and the water lightened via using levels.  This should help bring out some of the wonderful detail in the waves and draw less attention to the sky.', '2006-07-08 12:57:06.000000', NULL, 1),
(2600454, 356269, 60047, '<td valign="top">Nice motion effect. I would prefer a more interesting background, though.</td>', 'Nice motion effect. I would prefer a more interesting background, though.', '2006-07-08 12:58:42.000000', NULL, 1),
(2600458, 358601, 40490, '<td valign="top">Wow! Either you have a REALLY telephoto lens, high megapixel count to cro pthat much, or you were really close to the launch site, and that''s awesome!</td>', 'Wow! Either you have a REALLY telephoto lens, high megapixel count to cro pthat much, or you were really close to the launch site, and that''s awesome!', '2006-07-08 13:00:04.000000', NULL, 1),
(2600460, 358516, 61679, '<td valign="top">This image is very unique and artistic.  As presented the bird really isn''t the focal point of the composition but instead the bird house.  This really weakens the stationary statement of this image, as bird houses are normally stationary.  If I were to print this image to hang on the wall, I would be tempted to clone out the bird completely.</td>', 'This image is very unique and artistic.  As presented the bird really isn''t the focal point of the composition but instead the bird house.  This really weakens the stationary statement of this image, as bird houses are normally stationary.  If I were to print this image to hang on the wall, I would be tempted to clone out the bird completely.', '2006-07-08 13:01:34.000000', NULL, 1),
(2600463, 355365, 60047, '<td valign="top">I love the "expression" on the bug''s face - and the title to go with it!</td>', 'I love the "expression" on the bug''s face - and the title to go with it!', '2006-07-08 13:03:04.000000', NULL, 1),
(2600465, 356158, 40490, '<td valign="top">Okay, wow, that''s just creepy and cool! and it is all standing still! Even the title, except for the woman running her hand through her hair, of course.</td>', 'Okay, wow, that''s just creepy and cool! and it is all standing still! Even the title, except for the woman running her hand through her hair, of course.', '2006-07-08 13:03:28.000000', NULL, 1),
(2600470, 356424, 61679, '<td valign="top">The concept of several small objects being tied together and made stationary is a unique take on this challenge and I think very suitable.  The lighting and depth of field in this image is very good and upon revisiting, I''ve bumped this up to a 6.  The picture could have been much stronger if you would have removed the distacting objects on the far right before you captured the image.</td>', 'The concept of several small objects being tied together and made stationary is a unique take on this challenge and I think very suitable.  The lighting and depth of field in this image is very good and upon revisiting, I''ve bumped this up to a 6.  The picture could have been much stronger if you would have removed the distacting objects on the far right before you captured the image.', '2006-07-08 13:05:07.000000', NULL, 1),
(2600483, 358690, 60047, '<td valign="top">Fascinating shot</td>', 'Fascinating shot', '2006-07-08 13:08:16.000000', NULL, 1),
(2600491, 358629, 60047, '<td valign="top">Noticibly crisp.</td>', 'Noticibly crisp.', '2006-07-08 13:11:00.000000', NULL, 1),
(2600553, 356965, 32997, '<td valign="top">nice creative way to take this shot..the trucks with their tonal range are very dynamic on their own...<br/>nice ahndling of sturation/tones/hues..glad they are not overdone..</td>', 'nice creative way to take this shot..the trucks with their tonal range are very dynamic on their own...nice ahndling of sturation/tones/hues..glad they are not overdone..', '2006-07-08 13:40:11.000000', NULL, 1),
(2600569, 356454, 31133, '<td valign="top">The processing of this image is cool. The only thing that distracts me are the mistakes around the edges. I''m not trying to be mean I promise! I have the same issues a lot of times. I just wanted to let you know in case you find it helpful to know. The image quality is perfect with respect to sharpness. I like the colors you''ve chosen, too.</td>', 'The processing of this image is cool. The only thing that distracts me are the mistakes around the edges. I''m not trying to be mean I promise! I have the same issues a lot of times. I just wanted to let you know in case you find it helpful to know. The image quality is perfect with respect to sharpness. I like the colors you''ve chosen, too.', '2006-07-08 13:50:19.000000', NULL, 1),
(2600574, 356853, 31133, '<td valign="top">Hmmm, there''s a little too much to look at in this image for me, plus the gothic glow is a little strong, particularly on the left. The cloth is pretty and the color of the sky is gorgeous. I feel like a lot is missing by being cropped sort of here and there, rather than showing, for example, the whole left hand side, the whole wheel, etc.</td>', 'Hmmm, there''s a little too much to look at in this image for me, plus the gothic glow is a little strong, particularly on the left. The cloth is pretty and the color of the sky is gorgeous. I feel like a lot is missing by being cropped sort of here and there, rather than showing, for example, the whole left hand side, the whole wheel, etc.', '2006-07-08 13:52:59.000000', NULL, 1),
(2600577, 358601, 31133, '<td valign="top">What a shot! There''s something weird with the sky to the left of the jet ... looks like you may have tried to clone something out, but it kind of got messed up. I REALLY like the detail you got in the white part of the jet exhaust. The contrast between still and rocket fast makes this interesting.</td>', 'What a shot! There''s something weird with the sky to the left of the jet ... looks like you may have tried to clone something out, but it kind of got messed up. I REALLY like the detail you got in the white part of the jet exhaust. The contrast between still and rocket fast makes this interesting.', '2006-07-08 13:55:30.000000', NULL, 1),
(2600584, 357386, 31133, '<td valign="top">I really like this. Technically, it''s nearly perfect (and was probably tricky to get the exposure correct on that fillament). The reason I like it is because of the soft golden color and the interesting detail at the base  - and it''s different than many of the entries! I might have cropped the top out somewhat, but that''s just me.</td>', 'I really like this. Technically, it''s nearly perfect (and was probably tricky to get the exposure correct on that fillament). The reason I like it is because of the soft golden color and the interesting detail at the base  - and it''s different than many of the entries! I might have cropped the top out somewhat, but that''s just me.', '2006-07-08 14:00:10.000000', NULL, 1),
(2600587, 355916, 31133, '<td valign="top">Beautiful!! The stillness of that buck is gorgeous. Love the dof you''ve chosen.  I hope you do well with this one!</td>', 'Beautiful!! The stillness of that buck is gorgeous. Love the dof you''ve chosen.  I hope you do well with this one!', '2006-07-08 14:05:51.000000', NULL, 1),
(2600588, 358408, 31133, '<td valign="top">Tack sharp and veryinteresting face, but there''s a bit too much darkness in his face and harsh shadow overall. I''d like to be able to see more of that look of intense concentration, particularly around the eyes.</td>', 'Tack sharp and veryinteresting face, but there''s a bit too much darkness in his face and harsh shadow overall. I''d like to be able to see more of that look of intense concentration, particularly around the eyes.', '2006-07-08 14:08:21.000000', NULL, 1),
(2600593, 355431, 31133, '<td valign="top">Doll or toy shots are not my favorite, but you''ve got beautiful depth in your black and white here! The legs of the right figurine and the face of the left are blown out and slightly distracting, but I really, really like the basket and the general great detail you got in the shadows.</td>', 'Doll or toy shots are not my favorite, but you''ve got beautiful depth in your black and white here! The legs of the right figurine and the face of the left are blown out and slightly distracting, but I really, really like the basket and the general great detail you got in the shadows.', '2006-07-08 14:14:15.000000', NULL, 1),
(2600597, 355634, 31133, '<td valign="top">What an interesting (and huge!) sculpture ths is! My favorite part of this image is the greens, yellows, and lights in and around the buildings to the left. Very nice with the stars!</td>', 'What an interesting (and huge!) sculpture ths is! My favorite part of this image is the greens, yellows, and lights in and around the buildings to the left. Very nice with the stars!', '2006-07-08 14:16:14.000000', NULL, 1),
(2600599, 358187, 31133, '<td valign="top">Ooooh, looks like a beautiful place!</td>', 'Ooooh, looks like a beautiful place!', '2006-07-08 14:17:52.000000', NULL, 1),
(2600619, 357463, 31133, '<td valign="top">This poor baby wants some attention from you :-) I hope he or she isn''t really stuck, but it does look like that. What sad eyes... great job catching the detail in the face and hair!</td>', 'This poor baby wants some attention from you :-) I hope he or she isn''t really stuck, but it does look like that. What sad eyes... great job catching the detail in the face and hair!', '2006-07-08 14:31:53.000000', NULL, 1),
(2600622, 356502, 61679, '<td valign="top">The focus on the insect is pretty good but the little fellow sure didn''t cooperate with his pose.  Here are a few suggestions you might want to try to see if they improve this image.  It might be possible to remove the lighter green areas of the background if you used a square crop.  This would help eliminate a couple of distractions that draw a person''s eyes away from the main subject.  You may also want to try to bring out some detail in the body of the insect by playing around with levels.  You made a pretty decent capture; however, the competition was pretty tough this challenge.</td>', 'The focus on the insect is pretty good but the little fellow sure didn''t cooperate with his pose.  Here are a few suggestions you might want to try to see if they improve this image.  It might be possible to remove the lighter green areas of the background if you used a square crop.  This would help eliminate a couple of distractions that draw a person''s eyes away from the main subject.  You may also want to try to bring out some detail in the body of the insect by playing around with levels.  You made a pretty decent capture; however, the competition was pretty tough this challenge.', '2006-07-08 14:32:28.000000', NULL, 1),
(2600623, 355939, 31133, '<td valign="top">hehee, this gives me a big smile. I''m older than the hills and I remember this game! Love the hot pink and the hand on the radio. The girl''s expression is to die for ... so cute!</td>', 'hehee, this gives me a big smile. I''m older than the hills and I remember this game! Love the hot pink and the hand on the radio. The girl''s expression is to die for ... so cute!', '2006-07-08 14:33:26.000000', NULL, 1),
