(2600733, 356236, 47933, '<td valign="top">Very pretty. I like the lighting you''ve captured on the mountain.</td>', 'Very pretty. I like the lighting you''ve captured on the mountain.', '2006-07-08 15:14:26.000000', NULL, 1),
(2600734, 356144, 61679, '<td valign="top">The technical aspects of this image are really pretty good.  The focus is sharp, the lighting is good, and the colors are well balanced.  However, stacking three normally stationary objects on top of each other is not the strongest subject for this challenge.</td>', 'The technical aspects of this image are really pretty good.  The focus is sharp, the lighting is good, and the colors are well balanced.  However, stacking three normally stationary objects on top of each other is not the strongest subject for this challenge.', '2006-07-08 15:14:48.000000', NULL, 1),
