(2606922, 357814, 55199, '<td valign="top">Looks like fireworks in B/W. I''d prefer a closer cropping on the right and bottom; too much black.  I am having difficulty seeing how fireworks meets the challenge.</td>', 'Looks like fireworks in B/W. I''d prefer a closer cropping on the right and bottom; too much black.  I am having difficulty seeing how fireworks meets the challenge.', '2006-07-10 12:10:14.000000', NULL, 1),
(2606935, 356548, 55199, '<td valign="top">The focus on the face is good, but the composition makes my eyes travel to the ends of the wings which is out of focus.  And, the brighter pinkish area at the top is distracting. So, I think a different composition or crop would be better.</td>', 'The focus on the face is good, but the composition makes my eyes travel to the ends of the wings which is out of focus.  And, the brighter pinkish area at the top is distracting. So, I think a different composition or crop would be better.', '2006-07-10 12:14:10.000000', NULL, 1),
(2606957, 358241, 55199, '<td valign="top">There is potential here. I wish I could see this a little more in context.  It definitely looks in-operable. You title would be better as "Goin'' No Where."</td>', 'There is potential here. I wish I could see this a little more in context.  It definitely looks in-operable. You title would be better as "Goin'' No Where."', '2006-07-10 12:19:51.000000', NULL, 1),
(2606966, 358384, 55199, '<td valign="top">I think a different perspective could make this more interesting.</td>', 'I think a different perspective could make this more interesting.', '2006-07-10 12:23:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2606976, 357843, 50695, '<td valign="top">I love your title.</td>', 'I love your title.', '2006-07-10 12:26:38.000000', NULL, 1),
(2606982, 358515, 50695, '<td valign="top">interesting composition.</td>', 'interesting composition.', '2006-07-10 12:27:56.000000', NULL, 1),
(2606990, 358406, 59891, '<td valign="top">I enjoy the idea here.  The selective desat doesn''t add anything for me.  I also find the composition a bit cluttered.  I''m especially disturbed by the cut off head at the bottom.</td>', 'I enjoy the idea here.  The selective desat doesn''t add anything for me.  I also find the composition a bit cluttered.  I''m especially disturbed by the cut off head at the bottom.', '2006-07-10 12:30:54.000000', NULL, 1),
(2606991, 358566, 55199, '<td valign="top">cool :)  I had an idea like this, but not an environment in which to carry it out, nor an attractive model to stand very still for me.  I''m finding the white crosswalk symbol at the top distracting, but otherwise, nice job. :)</td>', 'cool :)  I had an idea like this, but not an environment in which to carry it out, nor an attractive model to stand very still for me.  I''m finding the white crosswalk symbol at the top distracting, but otherwise, nice job. :)', '2006-07-10 12:31:38.000000', NULL, 1),
(2606996, 357411, 59891, '<td valign="top">I appreciate the simplicity here, but think the composition could use a little more thought.  Is there a reason that the background shadow intersects with the subject''s chin?  The shallow depth of field works to good advantage for the background, but perhaps needs to be just a bit deeper to make sure the silhoutte is sharply focused throughout.</td>', 'I appreciate the simplicity here, but think the composition could use a little more thought.  Is there a reason that the background shadow intersects with the subject''s chin?  The shallow depth of field works to good advantage for the background, but perhaps needs to be just a bit deeper to make sure the silhoutte is sharply focused throughout.', '2006-07-10 12:35:27.000000', NULL, 1),
(2607002, 356263, 55199, '<td valign="top">Ooo.. pretty colors. :)  If the focus were a wee bit clearer on your damsel flies face, this would probably do quite well.</td>', 'Ooo.. pretty colors. :)  If the focus were a wee bit clearer on your damsel flies face, this would probably do quite well.', '2006-07-10 12:37:59.000000', NULL, 1),
(2607003, 356548, 59891, '<td valign="top">Nice capture - I don''t know that I''ve ever before been this familiar with a moth''s face!  There is something about the composition that is not working for me, but I can''t put my finger on just what it is.  I like the colors and the perspective lines.  Would have preferred a slightly deeper field.  I know this must have been a tricky shot to take.</td>', 'Nice capture - I don''t know that I''ve ever before been this familiar with a moth''s face!  There is something about the composition that is not working for me, but I can''t put my finger on just what it is.  I like the colors and the perspective lines.  Would have preferred a slightly deeper field.  I know this must have been a tricky shot to take.', '2006-07-10 12:38:56.000000', NULL, 1),
(2607007, 358144, 55199, '<td valign="top">No body and dark background makes this a bit eerie feeling. Kinda creepy.  Still, its a nice photo.</td>', 'No body and dark background makes this a bit eerie feeling. Kinda creepy.  Still, its a nice photo.', '2006-07-10 12:41:16.000000', NULL, 1),
(2607012, 355477, 59891, '<td valign="top">I like the colors here!  Composition is a little cluttered, though.  It must have been a challenge to find the right angle with the right lighting and still get that daylily in there.  Try experimenting with a really tight crop (even if it means cutting off part of the daylily or the bird on top) to see if that helps.  I would particularly recommend taking out the blue thing - very distracting.</td>', 'I like the colors here!  Composition is a little cluttered, though.  It must have been a challenge to find the right angle with the right lighting and still get that daylily in there.  Try experimenting with a really tight crop (even if it means cutting off part of the daylily or the bird on top) to see if that helps.  I would particularly recommend taking out the blue thing - very distracting.', '2006-07-10 12:43:33.000000', NULL, 1),
(2607015, 358582, 59891, '<td valign="top">A lovely spot and nice composition.  The colors in the lower half seem unnatural to me.  Is it really orange?</td>', 'A lovely spot and nice composition.  The colors in the lower half seem unnatural to me.  Is it really orange?', '2006-07-10 12:45:49.000000', NULL, 1),
(2607019, 355693, 55199, '<td valign="top">If they are stationary, thats gotta be hard on the muscles... ouch.  Photo would be better without the other people in the background (although i''m sure you couldn''t do anything about that). Also it looks a little out of focus or grainy.</td>', 'If they are stationary, thats gotta be hard on the muscles... ouch.  Photo would be better without the other people in the background (although i''m sure you couldn''t do anything about that). Also it looks a little out of focus or grainy.', '2006-07-10 12:47:58.000000', NULL, 1),
(2607023, 358308, 59891, '<td valign="top">Very humorous and a nice composition with a dramatic sky.  It might benefit from some of the post-processing tricks they are talking about on the Landscape Photo Learning Thread.  Check it out and see what you think.</td>', 'Very humorous and a nice composition with a dramatic sky.  It might benefit from some of the post-processing tricks they are talking about on the Landscape Photo Learning Thread.  Check it out and see what you think.', '2006-07-10 12:49:38.000000', NULL, 1),
(2607049, 358605, 59891, '<td valign="top">What a lovely evening sky!  There''s a lot I like about this image, but the legs for some reason bother me.  I think it''s because the torso is bisected by the treeline. And the body also bisects the image.  Maybe try some different crops - taking a bunch off the right side would (IMO) create a much more interesting composition right off the bat.  I''m also wondering how a seated pose would have worked silhoutted against the water rather than the sky...</td>', 'What a lovely evening sky!  There''s a lot I like about this image, but the legs for some reason bother me.  I think it''s because the torso is bisected by the treeline. And the body also bisects the image.  Maybe try some different crops - taking a bunch off the right side would (IMO) create a much more interesting composition right off the bat.  I''m also wondering how a seated pose would have worked silhoutted against the water rather than the sky...', '2006-07-10 12:58:14.000000', NULL, 1),
(2607051, 355925, 59891, '<td valign="top">Nicely done pic with a great title!  Good security, too - no heads and in the "old" BDUs...</td>', 'Nicely done pic with a great title!  Good security, too - no heads and in the "old" BDUs...', '2006-07-10 13:00:25.000000', NULL, 1),
(2607054, 356364, 59891, '<td valign="top">Oh, if only that tree weren''t back there!!!</td>', 'Oh, if only that tree weren''t back there!!!', '2006-07-10 13:01:07.000000', NULL, 1),
(2607073, 358460, 59891, '<td valign="top">Really distracting billboard and pole (or tree trunk?)  I''m sure you had reasons for choosing this angle, so some selective cropping might have helped.  Aren''t these "living statues" amazing!</td>', 'Really distracting billboard and pole (or tree trunk?)  I''m sure you had reasons for choosing this angle, so some selective cropping might have helped.  Aren''t these "living statues" amazing!', '2006-07-10 13:05:06.000000', NULL, 1),
(2607080, 354929, 39598, '<td valign="top">This photo looks like it was scanned.<br/>Especially those funny looking lines in the sky, to the top left of the photo.<br/>I also don''t get the dark stripe in the water.</td>', 'This photo looks like it was scanned.Especially those funny looking lines in the sky, to the top left of the photo.I also don''t get the dark stripe in the water.', '2006-07-10 13:07:39.000000', NULL, 1),
(2607084, 358325, 59891, '<td valign="top">Lovely, lovely light.  Nicely balance comp, though I might have cropped in just a bit more from the left to take out that bright red thing.</td>', 'Lovely, lovely light.  Nicely balance comp, though I might have cropped in just a bit more from the left to take out that bright red thing.', '2006-07-10 13:07:58.000000', NULL, 1),
(2607097, 356706, 59891, '<td valign="top">I''ll be interested to see where this was taken.  I haven''t seen bent tips on the blades around here.  A really lovely capture of the colors in the sky - even if they''ve been enhanced in post processing.</td>', 'I''ll be interested to see where this was taken.  I haven''t seen bent tips on the blades around here.  A really lovely capture of the colors in the sky - even if they''ve been enhanced in post processing.', '2006-07-10 13:12:18.000000', NULL, 1),
(2607105, 358677, 59891, '<td valign="top">At first I thought the bottle was taking a break LOL! The colors and composition are great, it''s just too bad that the subject wasn''t sitting at the closer bench.</td>', 'At first I thought the bottle was taking a break LOL! The colors and composition are great, it''s just too bad that the subject wasn''t sitting at the closer bench.', '2006-07-10 13:15:09.000000', NULL, 1),
(2607205, 355687, 59194, '<td valign="top">I really like this shot - all of the textures and contrast in the statue is awesome.</td>', 'I really like this shot - all of the textures and contrast in the statue is awesome.', '2006-07-10 13:39:51.000000', NULL, 1),
(2607280, 357489, 19311, '<td valign="top">Very nice capture of a mundane but somehow special moment.  I like the muted tones but really think the red is too much.  The subject is the people standing there more so than the bridge.  I think you could have left some red in it as to stand out a little, but as is, its far to bright. 6</td>', 'Very nice capture of a mundane but somehow special moment.  I like the muted tones but really think the red is too much.  The subject is the people standing there more so than the bridge.  I think you could have left some red in it as to stand out a little, but as is, its far to bright. 6', '2006-07-10 14:06:53.000000', NULL, 1),
(2607294, 357643, 19311, '<td valign="top">Try harder next time.  Almost anything would be better.  Dark, gloomy, or doomy would have been better alone.  Won''t affect your score though but good titles can help.</td>', 'Try harder next time.  Almost anything would be better.  Dark, gloomy, or doomy would have been better alone.  Won''t affect your score though but good titles can help.', '2006-07-10 14:10:57.000000', NULL, 1),
(2607296, 354802, 19311, '<td valign="top">Love the shot but don''t think this is really stationary. 6</td>', 'Love the shot but don''t think this is really stationary. 6', '2006-07-10 14:11:33.000000', NULL, 1),
(2607309, 355690, 27524, '<td valign="top">Staring....<br/>Very beautiful. Just not sure if sky stands so still :).</td>', 'Staring....Very beautiful. Just not sure if sky stands so still :).', '2006-07-10 14:16:47.000000', NULL, 1),
(2607311, 355916, 27524, '<td valign="top">Cool compozition :)... really like the tones of picture. Duo colors?</td>', 'Cool compozition :)... really like the tones of picture. Duo colors?', '2006-07-10 14:16:54.000000', NULL, 1),
(2607312, 358609, 27524, '<td valign="top">Ahh...these are who make circles in grain! :)<br/>Real nice comopozition and soft colors.</td>', 'Ahh...these are who make circles in grain! :)Real nice comopozition and soft colors.', '2006-07-10 14:16:56.000000', NULL, 1),
(2607313, 356444, 27524, '<td valign="top">Great photo...like the sky going dark.</td>', 'Great photo...like the sky going dark.', '2006-07-10 14:17:01.000000', NULL, 1),
(2607321, 354929, 19311, '<td valign="top">I really like the muted tones in this shot.  I wish you could see more of the bike though and less of the sky.</td>', 'I really like the muted tones in this shot.  I wish you could see more of the bike though and less of the sky.', '2006-07-10 14:18:44.000000', NULL, 1),
(2607322, 356637, 27524, '<td valign="top">Impressive buddy...great lights capture on his head. Great shot! Maximum rating.</td>', 'Impressive buddy...great lights capture on his head. Great shot! Maximum rating.', '2006-07-10 14:18:58.000000', NULL, 1),
(2607353, 358693, 19311, '<td valign="top">A cute picture of the squirell but could use a good bump in brightness and contrast.  Levels or curves would make a huge difference with this shot.</td>', 'A cute picture of the squirell but could use a good bump in brightness and contrast.  Levels or curves would make a huge difference with this shot.', '2006-07-10 14:25:40.000000', NULL, 1),
(2607500, 355916, 59095, '<td valign="top">wow.  if this is the actual scene. great shot.  i''m goint to presume it is. 9</td>', 'wow.  if this is the actual scene. great shot.  i''m goint to presume it is. 9', '2006-07-10 15:09:03.000000', NULL, 1),
(2607584, 356857, 55199, '<td valign="top">Is this actually across the road or is it along the edge of it?  I think the color version probably would have been much better because the green of the trees would help your rocks/mud stand out from the background better.</td>', 'Is this actually across the road or is it along the edge of it?  I think the color version probably would have been much better because the green of the trees would help your rocks/mud stand out from the background better.', '2006-07-10 15:36:17.000000', NULL, 1),
(2607636, 358315, 55199, '<td valign="top">Nice idea.  Love the reflections.  Lighting is a little harsh.</td>', 'Nice idea.  Love the reflections.  Lighting is a little harsh.', '2006-07-10 15:51:42.000000', NULL, 1),
(2607667, 358481, 55199, '<td valign="top">I bet this sends shudders down the spines of people who are afraid of spiders.  Your image gives a sense of impending trouble, as if all it needs is a little organ music before it slowly scampers onto someone''s neck, or pounces on some victim from out of the shadow.  Very nice capture.  The bits of spider silk are great too.</td>', 'I bet this sends shudders down the spines of people who are afraid of spiders.  Your image gives a sense of impending trouble, as if all it needs is a little organ music before it slowly scampers onto someone''s neck, or pounces on some victim from out of the shadow.  Very nice capture.  The bits of spider silk are great too.', '2006-07-10 15:59:14.000000', NULL, 1),
(2607697, 355889, 55199, '<td valign="top">The wheels on the bottom of that red boat are interesting.  However, I think the composition would be stronger without the red boat.  Nice proportion of sand/greenery/subject.</td>', 'The wheels on the bottom of that red boat are interesting.  However, I think the composition would be stronger without the red boat.  Nice proportion of sand/greenery/subject.', '2006-07-10 16:11:28.000000', NULL, 1),
(2607770, 356821, 55199, '<td valign="top">Nostalgic. :)</td>', 'Nostalgic. :)', '2006-07-10 16:34:02.000000', NULL, 1),
(2607793, 356042, 55199, '<td valign="top">Beautiful sunrise.  I wish the boats were somehow positioned differently to strengthen their value in your image. Very beautiful nonetheless.</td>', 'Beautiful sunrise.  I wish the boats were somehow positioned differently to strengthen their value in your image. Very beautiful nonetheless.', '2006-07-10 16:41:59.000000', NULL, 1),
(2607796, 357289, 55199, '<td valign="top">Lovely colors and natural lines.</td>', 'Lovely colors and natural lines.', '2006-07-10 16:43:25.000000', NULL, 1),
(2607853, 356614, 55199, '<td valign="top">Funny!  although, not very stationary.  I''m sure this would have done MUCH better in a different challenge. Great capture.</td>', 'Funny!  although, not very stationary.  I''m sure this would have done MUCH better in a different challenge. Great capture.', '2006-07-10 17:02:10.000000', NULL, 1),
(2607855, 358579, 17134, '<td valign="top">Roadkill usually scores low.. (see my portfolio :P)<br/>I tend to "like" it however</td>', 'Roadkill usually scores low.. (see my portfolio :P)I tend to "like" it however', '2006-07-10 17:03:07.000000', NULL, 1),
(2607880, 358579, 55199, '<td valign="top">Yuck!  hold your breath!  ;)</td>', 'Yuck!  hold your breath!  ;)', '2006-07-10 17:09:04.000000', NULL, 1),
(2607894, 357761, 55199, '<td valign="top">Peaceful.</td>', 'Peaceful.', '2006-07-10 17:12:51.000000', NULL, 1),
(2607949, 355690, 55199, '<td valign="top">Great capture of a very stormy sky!  Too bad it doesn''t really fit this challenge; it would have done well under a more suitable topic.</td>', 'Great capture of a very stormy sky!  Too bad it doesn''t really fit this challenge; it would have done well under a more suitable topic.', '2006-07-10 17:30:11.000000', NULL, 1),
(2607957, 356486, 11518, '<td valign="top">Very clever!  The bright highlight bothers me a tad but just a tad.  Well done.</td>', 'Very clever!  The bright highlight bothers me a tad but just a tad.  Well done.', '2006-07-10 17:32:40.000000', NULL, 1),
(2608057, 358641, 23430, '<td valign="top">I like your water background.</td>', 'I like your water background.', '2006-07-10 18:11:18.000000', NULL, 1),
(2608059, 358398, 23430, '<td valign="top">Like the leading lines and the movement of the train. Colour of the model is good too. Good shot.</td>', 'Like the leading lines and the movement of the train. Colour of the model is good too. Good shot.', '2006-07-10 18:12:34.000000', NULL, 1),
(2608060, 356039, 23430, '<td valign="top">Well composed shot and nice tones give this a real country feel.</td>', 'Well composed shot and nice tones give this a real country feel.', '2006-07-10 18:13:18.000000', NULL, 1),
(2608067, 358665, 23430, '<td valign="top">Awesome scene. Well composed.</td>', 'Awesome scene. Well composed.', '2006-07-10 18:18:11.000000', NULL, 1),
(2608071, 358437, 23430, '<td valign="top">These green hills look great.</td>', 'These green hills look great.', '2006-07-10 18:19:13.000000', NULL, 1),
(2608085, 358690, 23430, '<td valign="top">Great composition here with the leading line of the stick and the pose of the bird all against the plain background. I think a contrast boost may have totally nailed this shot. Good capture.</td>', 'Great composition here with the leading line of the stick and the pose of the bird all against the plain background. I think a contrast boost may have totally nailed this shot. Good capture.', '2006-07-10 18:24:21.000000', NULL, 1),
